package main

import (
	"bytes"
	"encoding/json"
	"log"
	"strings"
	"testing"
)

func TestProbeStructuredLogs(t *testing.T) {
	var buf bytes.Buffer
	log.SetOutput(&buf)
	log.SetFlags(0)
	defer func() { log.SetOutput(nil); log.SetFlags(log.LstdFlags) }()

	logLine("info", "listening on :8080", nil)
	line := strings.TrimSpace(buf.String())
	if line == "" {
		t.Fatal("nothing logged")
	}
	var entry map[string]any
	if err := json.Unmarshal([]byte(line), &entry); err != nil {
		t.Fatalf("log line is not one JSON object: %q", line)
	}
	if entry["level"] != "info" {
		t.Fatalf("level = %v", entry["level"])
	}
	if entry["msg"] != "listening on :8080" {
		t.Fatalf("msg = %v", entry["msg"])
	}

	// Fields merge in as top-level keys.
	buf.Reset()
	logLine("warn", "slow request", map[string]any{"ms": 42, "path": "/session"})
	line = strings.TrimSpace(buf.String())
	entry = map[string]any{}
	if err := json.Unmarshal([]byte(line), &entry); err != nil {
		t.Fatalf("field log line not json: %q", line)
	}
	if entry["ms"] != float64(42) || entry["path"] != "/session" || entry["level"] != "warn" {
		t.Fatalf("fields missing: %v", entry)
	}
	// One line only (no stray prints).
	if n := strings.Count(buf.String(), "\n"); n != 1 {
		t.Fatalf("expected exactly one line, got %d", n)
	}
}
EOF
go test -count=1 . ; rc=$? ; rm -f probe_log_test.go ; exit $rc

