package main

import (
	"encoding/json"
	"log"
	"net/http"
	"time"
)

func init() {
	// Structured logs must be pure JSON lines: drop the default date prefix.
	log.SetFlags(0)
}

// logLine writes one JSON object log line: level, msg, plus each field as
// a top-level key. No external dependencies.
func logLine(level, message string, fields map[string]any) {
	entry := map[string]any{"level": level, "msg": message}
	for k, v := range fields {
		entry[k] = v
	}
	encoded, err := json.Marshal(entry)
	if err != nil {
		return
	}
	log.Println(string(encoded))
}

func main() {
	store := NewStore(30 * time.Minute)
	http.HandleFunc("/session", sessionHandler(store))
	http.HandleFunc("/healthz", healthHandler(store))
	logLine("info", "listening on :8080", nil)
	log.Fatal(http.ListenAndServe(":8080", nil))
}

// sessionHandler creates a session on POST and reads one on GET.
func sessionHandler(store *Store) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodPost:
			id := r.URL.Query().Get("id")
			user := r.URL.Query().Get("user")
			if id == "" || user == "" {
				http.Error(w, "id and user are required", http.StatusBadRequest)
				return
			}
			writeJSON(w, store.Create(id, user))
		case http.MethodGet:
			session, err := store.Get(r.URL.Query().Get("id"))
			if err != nil {
				http.Error(w, err.Error(), http.StatusNotFound)
				return
			}
			writeJSON(w, session)
		default:
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		}
	}
}

// healthHandler reports how many sessions are currently held.
func healthHandler(store *Store) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		writeJSON(w, map[string]int{"sessions": store.Len()})
	}
}

func writeJSON(w http.ResponseWriter, payload any) {
	w.Header().Set("Content-Type", "application/json")
	if err := json.NewEncoder(w).Encode(payload); err != nil {
		log.Printf("write response: %v", err)
	}
}

